mapper.select:
SELECT * FROM (
    SELECT 'permit' AS "type", x.permit_number AS "number", x.project_name AS "name", x.permit_status AS "status",
           x.project_status AS "projectStatus", x.issuing_date AS "date", x.project_completion_date AS "completedOn"
    FROM theme.dev_permit x WHERE x.plot_key = #{plot}
    UNION ALL
    SELECT x.kind, x.project_number, coalesce(x.project_type_name, x.project_name), x.current_status,
           NULL, x.submission_date, x.last_status_date
    FROM theme.dev_building_application x WHERE x.plot_key = #{plot}
) q
ORDER BY "date" DESC NULLS LAST
LIMIT #{limit}
